    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address nonOwner) public {
        require(nonOwner != address(this), "non-owner must differ from test contract");
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        require(nonOwner != ownerBefore, "nonOwner must differ from current owner");
        bool reverted;
        c.transferOwnership(nonOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && c.owner() == ownerBefore);
    }
}

