    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address nonOwner) internal {
        vm.assume(nonOwner != address(this));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        vm.assume(nonOwner != ownerBefore);
        bool reverted;
        try c.transferOwnership(nonOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
